questionvariables.text:
/* Parallel sides of trapezium */
a: rand(5)+4;      /* 4..8 cm */
b: rand(6)+9;      /* 9..14 cm */

/* Trapezium height */
h: rand(5)+3;      /* 3..7 cm */

/* Prism length */
L: rand(6)+5;      /* 5..10 cm */

/* Area of trapezium */
cross_section_area: ((a+b)*h)/2;

/* Correct volume */
ta: cross_section_area*L;


/* Common incorrect answers */

/* Forgot to multiply by prism length */
wrong_area_only: cross_section_area;

/* Used rectangle formula instead of trapezium formula */
wrong_rectangle: b*h*L;
